#!/usr/bin/env node
"use strict";
// Independent reconstruction of an untrusted two-stack Z3 push-DFA model.
// Exact pop edges and reachable rows are regenerated by mitmCert, not copied
// from the solver. The generated theorem must pass original-source Lean.
const fs=require("node:fs"), path=require("node:path");
const {mitmCert,emit}=require("./q0-open-automata.cjs");
const [input,outdir]=process.argv.slice(2);
if(!input||!outdir)throw Error("usage: node emit-hard-mitm.cjs SYNTHESIS.json OUTDIR");
fs.mkdirSync(outdir,{recursive:true});
const model=JSON.parse(fs.readFileSync(input,"utf8"));
if(!model.left||!model.right){
 console.log("No SAT candidate; no Lean theorem generated");
 process.exit(0);
}
if(!["148","151"].includes(model.case))throw Error("unrecognized target");
const table=model.table.replace(/_/g,"");
if(table.length!==36)throw Error("invalid source table");
for(const [name,dfa] of [["left",model.left],["right",model.right]]){
 if(!Array.isArray(dfa)||dfa.length===0)throw Error(name+" missing");
 if(dfa.some(x=>!Array.isArray(x)||x.length!==2||x.some(j=>!Number.isInteger(j)||j<0||j>=dfa.length)))throw Error(name+" invalid transition");
 if(dfa[0][0]!==0)throw Error(name+" blank push must loop");
}
const cert=mitmCert(table,model.left,model.right);
if(!cert)throw Error("Z3 candidate fails exact source-controlled MITM closure");
const ns="BB6.Agent5HardMITM.Q0"+model.case;
let lean="import TwoSidedAutomata\nimport WeightedTNF\nset_option maxHeartbeats 0\nset_option maxRecDepth 100000\nopen BB6Coverage BB6.Agent13BlankDelay\n"+emit(cert,ns);
lean+="\nnamespace "+ns+"\ntheorem cover (B : Nat) : Cover (WeightedBound B) table :=\n  .leaf _ fun m hm => weighted_never B m (never m hm)\n#print axioms cover\nend "+ns+"\n";
fs.writeFileSync(path.join(outdir,"Q0HardMITM"+model.case+".lean"),lean);
const summary={case:model.case,table,sourceModel:"untrusted SMT, independently reconstructed",left:cert.left.push.length,right:cert.right.push.length,rows:cert.rows.length};
fs.writeFileSync(path.join(outdir,"summary.json"),JSON.stringify(summary,null,2)+"\n");
console.log(JSON.stringify(summary));
